// PRESETS = Werte aus ESP config.json (mqtt_main_topic, hostname)
// Projekt-Konstanten = mqtt_config.h (nicht ändern, außer Firmware/Zigbee auch)
const HA_DEVICE_PREFIX = 'gas_o_meter2';
const HA_MANUFACTURER = 'Custom';
const HA_MODEL = 'Gas-O-Meter2';
const EXPIRE_AFTER_SEC = 120 * 60;

const PRESETS = {
    mqtt_main_topic: 'gas-o-meter2',
    ha_device_name: 'gas-o-meter2'
};

function mqttTopicSlug(mainTopic) {
    let s = String(mainTopic || '').replace(/\//g, '_').replace(/-/g, '_').replace(/ /g, '');
    return s.length ? s : 'device';
}

flow.set('mqtt_main_topic', PRESETS.mqtt_main_topic);
flow.set('ha_device_name', PRESETS.ha_device_name);
flow.set('mqtt_topic_slug', mqttTopicSlug(PRESETS.mqtt_main_topic));
flow.set('ha_expire_after_sec', EXPIRE_AFTER_SEC);

node.status({ fill: 'green', shape: 'dot', text: PRESETS.mqtt_main_topic });
return null;

// Bei sichtbarem Gerät: Connect auslösen wenn nicht verbunden, Subscribe nur wenn connected → weniger "Not yet connected".
var status = flow.get('bleNotifyStatus') || '';
if (!status || status === 'generic-ble.status.missing') return null;
if (status === 'generic-ble.status.connected') {
    return msg;
}
return { topic: 'connect', payload: {} };

var t = (msg.status && msg.status.text) ? String(msg.status.text) : '';
flow.set('bleNotifyStatus', t);
return null;

// Nur bei Notify 0xFFF1: Nachricht zwischenspeichern, Read 0x2A26 anfordern.
const pl = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : (msg.payload || {});
const ch = pl.characteristics || {};
if (ch.fff1 === undefined) return null;
flow.set('lastNotifyMsg', msg);
return { topic: '2a26', payload: {} };

// Nur bei Read-Resultat 0x2A26: Firmware an gespeicherte Notify-Nachricht anhängen, an Parse/CTS/Raw weiterreichen.
const pl = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : (msg.payload || {});
const ch = pl.characteristics || {};
if (ch['2a26'] === undefined) return null;
let fw = ch['2a26'];
if (Buffer.isBuffer(fw)) fw = fw.toString('utf8').trim();
else if (fw && fw.type === 'Buffer' && Array.isArray(fw.data)) fw = Buffer.from(fw.data).toString('utf8').trim();
else if (typeof fw !== 'string') fw = 'unknown';
const last = flow.get('lastNotifyMsg');
flow.set('lastNotifyMsg', null);
if (!last) return null;
last.firmware = fw;
return last;

// Current Time 0x2A2B: Exact Time 256 (10 Bytes UTC) → ESP32 time_sync_set_hard()
// Wird nur bei echtem BLE-Notify ausgeführt (nicht bei BLE Mock).
const now = new Date();
const epoch = Math.floor(now.getTime() / 1000);
flow.set('ble_time_sync_epoch', epoch);

const buf = Buffer.alloc(10);
buf.writeUInt16LE(now.getUTCFullYear(), 0);
buf[2] = now.getUTCMonth() + 1;
buf[3] = now.getUTCDate();
buf[4] = now.getUTCHours();
buf[5] = now.getUTCMinutes();
buf[6] = now.getUTCSeconds();
buf[7] = (now.getUTCDay() === 0) ? 7 : now.getUTCDay();
buf[8] = 0;
buf[9] = 0;
msg.payload = { '2a2b': buf.toString('hex') };
return msg;

// Parse Gas-O-Meter2 Custom Characteristic 0xFFF1 → Format wie Zigbee2MQTT
// bv vom ESP in mV (transfer_ble) → V für MQTT/HA wie WiFi
// Rohformat: {"p":12345,"bv":3910,"bp":85,"bl":0}

let data = {};

try {
    let raw = msg.payload;
    if (typeof raw === 'object' && raw.characteristics && raw.characteristics.fff1) {
        raw = raw.characteristics.fff1;
    } else if (typeof raw === 'object' && raw.fff1) {
        raw = raw.fff1;
    }
    if (raw && typeof raw === 'object' && raw.type === 'Buffer' && Array.isArray(raw.data)) {
        raw = Buffer.from(raw.data).toString('utf8');
    }
    if (Buffer.isBuffer(raw)) {
        raw = raw.toString('utf8');
    }
    if (typeof raw === 'string') {
        data = JSON.parse(raw);
        // Generic BLE in (useString: true): Nutzdaten in characteristics.fff1 (Buffer)
        if (data && data.characteristics && data.characteristics.fff1) {
            const fff1 = data.characteristics.fff1;
            if (fff1.type === 'Buffer' && Array.isArray(fff1.data)) {
                data = JSON.parse(Buffer.from(fff1.data).toString('utf8'));
            } else if (Buffer.isBuffer(fff1)) {
                data = JSON.parse(fff1.toString('utf8'));
            }
        }
    } else if (typeof raw === 'object' && raw !== null && !Buffer.isBuffer(raw)) {
        data = raw;
    }

    const p = data.p || 0;
    const bv = data.bv || 0;
    const bp = data.bp || 0;
    // Null-Abfrage: periodische BLE-Reads (z. B. alle 2 s) liefern oft 0/0/0 – nicht weitergeben
    if (p === 0 && bv === 0 && bp === 0) {
        return null;
    }

    const gasM3 = p / 100;
    msg.payload = {
        gas: gasM3,
        battery: bp,
        battery_voltage: Math.round(bv) / 1000,
        battery_low: (data.bl || 0) === 1,
        firmware_version: msg.firmware || 'unknown',
        timestamp: new Date().toISOString()  // UTC ISO (lesbar); ntp_status separat als Epoch/-1
    };

    return msg;
} catch (error) {
    node.error('Parse Error: ' + error.message, msg);
    return null;
}

// Pro Feld eigene Ausgabe (wie ESP transfer_mqtt)
// ntp_status: flow.ble_time_sync_epoch nach „CTS Write (Zeit-Sync)“ / „BLE Zeit schreiben“
const base = flow.get('mqtt_main_topic') || 'gas-o-meter2';
const p = msg.payload;
if (typeof p !== 'object' || p === null) return null;
const str = (v) => (typeof v === 'object' ? JSON.stringify(v) : String(v));
const low = p.battery_low ? 'true' : 'false';
let ntpEpoch = flow.get('ble_time_sync_epoch');
if (typeof ntpEpoch !== 'number' || !Number.isFinite(ntpEpoch) || ntpEpoch < 1) {
  ntpEpoch = -1;
} else {
  ntpEpoch = Math.floor(ntpEpoch);
}
node.send([
  [{ topic: base + '/gas', payload: str(p.gas) }],
  [{ topic: base + '/battery', payload: str(p.battery) }],
  [{ topic: base + '/battery_voltage', payload: str(p.battery_voltage) }],
  [{ topic: base + '/battery_low', payload: low }],
  [{ topic: base + '/firmware_version', payload: str(p.firmware_version) }],
  [{ topic: base + '/timestamp', payload: str(p.timestamp) }],
  [{ topic: base + '/rssi', payload: '0' }],
  [{ topic: base + '/ntp_status', payload: String(ntpEpoch) }],
  [{ topic: base + '/status', payload: 'online' }]
]);
return null;

const base = flow.get('mqtt_main_topic') || 'gas-o-meter2';
msg.topic = base + '/data';
return msg;

// Optional: Datenbank-Integration
// TODO: node-red-node-sqlite oder node-red-contrib-influxdb
return msg;

var enable = msg.payload === true;
const HA_DEVICE_PREFIX = 'gas_o_meter2';
const HA_MANUFACTURER = 'Custom';
const HA_MODEL = 'Gas-O-Meter2';
const EXPIRE_AFTER_SEC = flow.get('ha_expire_after_sec') || (120 * 60);

var main = flow.get('mqtt_main_topic') || 'gas-o-meter2';
var slug = flow.get('mqtt_topic_slug');
if (!slug) {
    slug = String(main).replace(/\//g, '_').replace(/-/g, '_').replace(/ /g, '');
    if (!slug.length) { slug = 'device'; }
}
var stateData = main + '/data';
var stateRssi = main + '/rssi';
var stateNtp = main + '/ntp_status';
var stateStatus = main + '/status';
var devId = HA_DEVICE_PREFIX + '_' + slug;
var deviceName = flow.get('ha_device_name') || main;

function uniqueId(tail) {
    return HA_DEVICE_PREFIX + '_' + slug + '_' + tail;
}
function haPath(comp, tail) {
    return 'homeassistant/' + comp + '/' + uniqueId(tail) + '/config';
}
function devBlock() {
    return {
        identifiers: [devId],
        name: deviceName,
        manufacturer: HA_MANUFACTURER,
        model: HA_MODEL
    };
}
function availFields() {
    return {
        expire_after: EXPIRE_AFTER_SEC,
        availability_topic: stateStatus,
        payload_available: 'online',
        payload_not_available: 'offline'
    };
}
function entity(comp, tail, fields, stateTopic) {
    var payload = Object.assign({}, availFields(), fields, {
        unique_id: uniqueId(tail),
        state_topic: stateTopic || stateData,
        device: devBlock()
    });
    return { topic: haPath(comp, tail), payload: payload };
}

var configs = [
    entity('sensor', 'gas', {
        name: 'Gas Counter',
        value_template: '{{ value_json.gas }}',
        unit_of_measurement: 'm\u00b3',
        device_class: 'gas',
        state_class: 'total_increasing',
        icon: 'mdi:meter-gas'
    }),
    entity('sensor', 'battery', {
        name: 'Battery',
        value_template: '{{ value_json.battery }}',
        unit_of_measurement: '%',
        device_class: 'battery',
        state_class: 'measurement',
        icon: 'mdi:battery'
    }),
    entity('sensor', 'voltage', {
        name: 'Battery Voltage',
        value_template: '{{ value_json.battery_voltage }}',
        unit_of_measurement: 'V',
        device_class: 'voltage',
        state_class: 'measurement',
        icon: 'mdi:flash'
    }),
    entity('binary_sensor', 'battery_low', {
        name: 'Battery Low',
        value_template: '{% if value_json.battery_low %}ON{% else %}OFF{% endif %}',
        payload_on: 'ON',
        payload_off: 'OFF',
        device_class: 'battery',
        icon: 'mdi:battery-alert'
    }),
    entity('sensor', 'firmware', {
        name: 'Firmware',
        value_template: '{{ value_json.firmware_version }}',
        icon: 'mdi:information',
        entity_category: 'diagnostic'
    }),
    entity('sensor', 'rssi', {
        name: 'RSSI',
        value_template: '{{ value | int }}',
        unit_of_measurement: 'dBm',
        device_class: 'signal_strength',
        state_class: 'measurement',
        entity_category: 'diagnostic'
    }, stateRssi),
    entity('sensor', 'ntp_status', {
        name: 'Last NTP Sync',
        device_class: 'timestamp',
        value_template: '{{ as_datetime(value) }}',
        entity_category: 'diagnostic'
    }, stateNtp)
];

var messages = [];
for (var i = 0; i < configs.length; i++) {
    messages.push({
        topic: configs[i].topic,
        payload: enable ? JSON.stringify(configs[i].payload) : '',
        retain: true
    });
}
node.status({ text: enable ? ('AN (' + configs.length + ')') : 'AUS' });
return [messages];
